def normalize_paths(lines):
    result = []
    seen = set()
    for line in lines:
        path = line.strip()
        if not path or path.startswith("#"):
            continue
        path = path.replace("\\", "/")
        while path.startswith("./"):
            path = path[2:]
        if path and path not in seen:
            seen.add(path)
            result.append(path)
    return result

