from copy import deepcopy


def apply_changes(state, operations):
    if not isinstance(operations, list):
        raise ValueError("operations must be a list")

    changes = {}

    for operation in operations:
        if not isinstance(operation, dict):
            raise ValueError("each operation must be a dictionary")

        kind = operation.get("kind")
        if kind == "put":
            required = {"kind", "id", "expected", "deps"}
        elif kind == "delete":
            required = {"kind", "id", "expected"}
        else:
            raise ValueError("unknown operation kind")

        if set(operation) != required:
            raise ValueError("operation has missing or unknown fields")

        name = operation["id"]
        if not isinstance(name, str) or not name:
            raise ValueError("operation ID must be a nonempty string")
        if name in changes:
            raise ValueError("duplicate operation ID")

        expected = operation["expected"]
        exists = name in state

        if exists:
            if (
                not isinstance(expected, int)
                or isinstance(expected, bool)
                or expected < 0
                or expected != state[name]["revision"]
            ):
                raise ValueError("expected revision does not match original state")
        elif kind == "delete":
            raise ValueError("cannot delete an absent node")
        elif expected is not None:
            raise ValueError("a new node requires expected=None")

        if kind == "delete":
            changes[name] = None
            continue

        deps = operation["deps"]
        if not isinstance(deps, list):
            raise ValueError("dependencies must be a list")

        seen = set()
        for dependency in deps:
            if not isinstance(dependency, str) or not dependency:
                raise ValueError("dependency names must be nonempty strings")
            if dependency == name:
                raise ValueError("self-dependency is invalid")
            if dependency in seen:
                raise ValueError("duplicate dependency")
            seen.add(dependency)

        changes[name] = {
            "revision": state[name]["revision"] + 1 if exists else 0,
            "deps": sorted(deps),
        }

    result = deepcopy(state)

    for name in sorted(changes):
        replacement = changes[name]
        if replacement is None:
            del result[name]
        else:
            result[name] = replacement

    incoming = {name: 0 for name in result}
    for record in result.values():
        for dependency in record["deps"]:
            if dependency not in result:
                raise ValueError("final graph contains a dangling reference")
            incoming[dependency] += 1

    ready = [name for name, count in incoming.items() if count == 0]
    visited = 0

    while ready:
        name = ready.pop()
        visited += 1
        for dependency in result[name]["deps"]:
            incoming[dependency] -= 1
            if incoming[dependency] == 0:
                ready.append(dependency)

    if visited != len(result):
        raise ValueError("final graph contains a cycle")

    return result

